"""Replay the hosted smoke evaluation; preserve refusals and completed evidence."""
import argparse,json,os,time,urllib.request,urllib.error
from pathlib import Path
p=argparse.ArgumentParser(); p.add_argument('--attempt',required=True); p.add_argument('--timeout',type=int,default=45); args=p.parse_args()
root=Path(__file__).resolve().parent; out=root/args.attempt; out.mkdir(exist_ok=True)
base=os.environ['MCPJAM_API_URL'].rstrip('/'); key=[REDACTED]'MCPJAM_API_KEY']
def call(method,path,body=None):
 headers={'Authorization':'Bearer '+key,'Content-Type':'application/json','x-mcpjam-launcher':'repeatable-arithmetic-smoke'}
 if method=='POST': headers['Idempotency-Key']='arithmetic-smoke-'+args.attempt
 req=urllib.request.Request(base+path,data=None if body is None else json.dumps(body).encode(),headers=headers,method=method)
 try:
  with urllib.request.urlopen(req,timeout=15) as r: return r.status,json.load(r)
 except urllib.error.HTTPError as e: return e.code,json.load(e)
