 (out/(name+'.json')).write_text(json.dumps({'httpStatus':status,'body':data},indent=2)+'\n'); print(name,status,json.dumps(data),flush=True)
path='/projects/project_fixture/eval-runs'; payload=json.loads((root/'run-request.json').read_text())
status,data=call('POST',path,payload); save('launch',status,data)
if status!=202: raise SystemExit(2)
run_id=data['runId']; deadline=time.monotonic()+args.timeout
while time.monotonic()<deadline:
