 if status!=200: raise SystemExit(3)
 if data.get('status') in ['completed','failed','cancelled','succeeded','error']: break
 time.sleep(2)
else: raise SystemExit('Polling timeout: run may still be active; read saved runId before relaunching.')
for suffix in ['iterations','decision-summary']:
